var config = $("Config").first().json;
var apifyToken = config.APIFY_API_TOKEN || '';
var sessionId = config.IG_SESSION_ID || '';
var MAX_FOLLOWS = 13;

var ghlHeaders = {
  'Authorization': 'Bearer REPLACE_WITH_GHL_API_TOKEN',
  'Content-Type': 'application/json',
  'Version': '2021-07-28'
};
var locationId = 'KM3KkAQFgG3bByTZmWLL';
var today = new Date().toISOString().split('T')[0];

var allContacts = [];
try {
  var res = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://services.leadconnectorhq.com/contacts/search',
    headers: ghlHeaders,
    body: JSON.stringify({
      locationId: locationId,
      pageLimit: 100,
      filters: [{ field: 'tags', operator: 'contains', value: 'qualified' }]
    })
  });
  allContacts = res.contacts || [];
} catch (e) {
  return [{ json: { followMessage: 'GHL error: ' + e.message, followAttempted: 0, followSuccess: 0, followFailed: 0, followedAccounts: 'None', apifyRunId: '', runDate: today, toFollowContacts: [] } }];
}

var toFollow = [];
for (var i = 0; i < allContacts.length; i++) {
  var c = allContacts[i];
  var tags = c.tags || [];
  var isFollowed = false;
  for (var t = 0; t < tags.length; t++) {
    if (tags[t] === 'ig-followed') { isFollowed = true; }
  }
  if (isFollowed) { continue; }
  var website = c.website || '';
  var match = website.match(/instagram\.com\/([a-zA-Z0-9._]+)/);
  if (!match) { continue; }
  toFollow.push({ contactId: c.id, name: c.firstName || c.lastName || '', username: match[1], tags: tags });
  if (toFollow.length >= MAX_FOLLOWS) { break; }
}

if (toFollow.length === 0) {
  return [{ json: { followMessage: 'No new qualified contacts to follow today', followAttempted: 0, followSuccess: 0, followFailed: 0, followedAccounts: 'None', apifyRunId: '', runDate: today, toFollowContacts: [] } }];
}

var usernames = [];
for (var j = 0; j < toFollow.length; j++) {
  usernames.push(toFollow[j].username);
}

var runId = '';
var actorError = '';
try {
  var runRes = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.apify.com/v2/acts/synk~instagram-auto-follow/runs?token=' + apifyToken,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      sessionCookie: sessionId,
      usersToFollow: usernames,
      accountType: 'aged',
      maxFollowsPerRun: MAX_FOLLOWS,
      delayBetweenFollows: 45,
      randomDelayVariation: 20
    })
  });
  var runData = runRes.data || runRes;
  runId = runData.id || '';
} catch (e) {
  actorError = e.message || String(e);
}

if (actorError || !runId) {
  return [{ json: {
    followMessage: 'Apify actor failed to start - no contacts tagged: ' + (actorError || 'no run ID returned'),
    followAttempted: usernames.length,
    followSuccess: 0,
    followFailed: usernames.length,
    followedAccounts: usernames.join(', '),
    apifyRunId: '',
    runDate: today,
    toFollowContacts: []
  } }];
}

return [{ json: {
  followMessage: 'Actor started - waiting to confirm completion',
  followAttempted: usernames.length,
  followSuccess: 0,
  followFailed: 0,
  followedAccounts: usernames.join(', '),
  apifyRunId: runId,
  runDate: today,
  toFollowContacts: toFollow
} }];

var config = $("Config").first().json;
var apifyToken = config.APIFY_API_TOKEN || '';

var prev = $input.first().json;
var runId = prev.apifyRunId || '';
var runDate = prev.runDate || new Date().toISOString().split('T')[0];
var toFollowContacts = prev.toFollowContacts || [];
var followedAccounts = prev.followedAccounts || 'None';
var followAttempted = prev.followAttempted || 0;

if (!runId || toFollowContacts.length === 0) {
  return [{ json: {
    followMessage: prev.followMessage || 'No run to check',
    followAttempted: followAttempted,
    followSuccess: 0,
    followFailed: followAttempted,
    followedAccounts: followedAccounts,
    apifyRunId: runId,
    runDate: runDate,
    costUsd: 0
  } }];
}

var ghlHeaders = {
  'Authorization': 'Bearer REPLACE_WITH_GHL_API_TOKEN',
  'Content-Type': 'application/json',
  'Version': '2021-07-28'
};

var runStatus = '';
var statusError = '';
var costUsd = 0;

try {
  var statusRes = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.apify.com/v2/actor-runs/' + runId + '?token=' + apifyToken
  });
  var statusData = statusRes.data || statusRes;
  runStatus = statusData.status || '';
  costUsd = statusData.usageTotalUsd || 0;
} catch (e) {
  statusError = e.message || String(e);
}

if (statusError) {
  return [{ json: {
    followMessage: 'Could not check run status: ' + statusError + ' - contacts NOT tagged',
    followAttempted: followAttempted,
    followSuccess: 0,
    followFailed: followAttempted,
    followedAccounts: followedAccounts,
    apifyRunId: runId,
    runDate: runDate,
    costUsd: 0
  } }];
}

if (runStatus !== 'SUCCEEDED') {
  return [{ json: {
    followMessage: 'Actor did not succeed (status: ' + runStatus + ') - contacts NOT tagged. Check Apify run: ' + runId,
    followAttempted: followAttempted,
    followSuccess: 0,
    followFailed: followAttempted,
    followedAccounts: followedAccounts,
    apifyRunId: runId,
    runDate: runDate,
    costUsd: costUsd
  } }];
}

for (var p = 0; p < toFollowContacts.length; p++) {
  var newTags = [];
  for (var q = 0; q < toFollowContacts[p].tags.length; q++) {
    newTags.push(toFollowContacts[p].tags[q]);
  }
  newTags.push('ig-followed');
  newTags.push('followed-date:' + runDate);
  try {
    await this.helpers.httpRequest({
      method: 'PUT',
      url: 'https://services.leadconnectorhq.com/contacts/' + toFollowContacts[p].contactId,
      headers: ghlHeaders,
      body: JSON.stringify({ tags: newTags })
    });
  } catch (e) {}
}

return [{ json: {
  followMessage: 'Follows confirmed and contacts tagged successfully',
  followAttempted: followAttempted,
  followSuccess: followAttempted,
  followFailed: 0,
  followedAccounts: followedAccounts,
  apifyRunId: runId,
  runDate: runDate,
  costUsd: costUsd
} }];

var prev = $input.first().json;
return [{ json: {
  'Date': prev.runDate || '',
  'Workflow': 'Phase 2B - Follow',
  'Actor': 'synk~instagram-auto-follow',
  'Run ID': prev.apifyRunId || '',
  'Actions Attempted': prev.followAttempted || 0,
  'Actions Succeeded': prev.followSuccess || 0,
  'Cost USD': prev.costUsd || 0,
  'Status': prev.followMessage || ''
} }];
